"""Pure validation helpers for resuming an interrupted Path A UI acceptance."""

from __future__ import annotations

import re


_RESUMED_DATASET = re.compile(r"boot-pool/user-data/ui-acceptance-[0-9]{14}[0-9a-f]{6}")


def validate_resumed_ui_dataset(dataset: str) -> str:
    """Accept only one dataset name generated by the Path A UI test."""
    if not dataset:
        return ""
    if _RESUMED_DATASET.fullmatch(dataset) is None:
        raise ValueError(
            "TRUENAS_TEST_RESUME_EXISTING_UI_DATASET must be an exact "
            "boot-pool/user-data/ui-acceptance-<14 digits><6 lowercase hex> dataset path"
        )
    return dataset


def resumed_ui_dataset_members(dataset: str) -> set[str]:
    """Return the only user dataset and zvol names allowed by this resume."""
    if not dataset:
        return set()
    validate_resumed_ui_dataset(dataset)
    return {
        dataset,
        f"{dataset}/vm-disk",
        f"{dataset}/cache-device",
    }


def unexpected_ui_root_snapshots(snapshot_names: list[str], cached_images: list[str]) -> list[str]:
    """Keep only each pinned middleware image's exact ``@image`` snapshot."""
    allowed = {f"{dataset}@image" for dataset in cached_images}
    return sorted(set(snapshot_names) - allowed)


def ui_root_internal_datasets(
    direct_names: list[str], root: str, image_name: str, *,
    stale_container_name: str = "", resumed_ui_dataset: str = "",
) -> tuple[list[str], list[str]]:
    """Validate the exact middleware cache plus an explicitly resumed UI dataset."""
    internal_root = f"{root}/.truenas_containers"
    allowed = {
        internal_root,
        f"{internal_root}/containers",
        f"{internal_root}/images",
    }
    if stale_container_name:
        allowed.add(f"{internal_root}/containers/{stale_container_name}")
    image_prefix = f"{internal_root}/images/{image_name}:"
    image_datasets = [
        name for name in direct_names
        if name.startswith(image_prefix) and "/" not in name[len(image_prefix):]
    ]
    allowed.update(image_datasets)

    resumed_members = resumed_ui_dataset_members(resumed_ui_dataset)
    allowed.update(resumed_members)
    if resumed_members:
        missing = sorted(resumed_members - set(direct_names))
        if missing:
            raise ValueError(
                f"UI resume cannot find all three explicitly named prior UI datasets/zvols: {missing!r}"
            )

    descendants = [name for name in direct_names if name.startswith(root + "/")]
    unexpected = sorted(set(descendants) - allowed)
    if unexpected:
        raise ValueError(
            "UI root contains datasets outside the middleware container tree, pinned image cache, "
            f"and explicitly resumed UI dataset: {unexpected!r}"
        )
    if not all(name[len(image_prefix):] for name in image_datasets):
        raise ValueError(f"UI root contains an invalid pinned image cache dataset: {image_datasets!r}")
    return descendants, image_datasets
